 public void Select(string id){canvas.SelectedId=id;RefreshList();Inspector();}
 static Button Button(Panel target,string label,Action action){var button=new Button{Content=label};button.Click+=(_,_)=>action();target.Children.Add(button);return button;}
 string Snapshot()=>JsonSerializer.Serialize(Document);
 void Checkpoint(){undo.Push(Snapshot());if(undo.Count>80){var keep=undo.Take(80).Reverse().ToArray();undo.Clear();foreach(var s in keep)undo.Push(s);}redo.Clear();}
 void Changed(bool list=false){draft.Save();canvas.InvalidateVisual();if(list)RefreshList();}
 void History(Stack<string> source,Stack<string> destination){if(source.Count==0)return;destination.Push(Snapshot());draft.Scene=JsonSerializer.Deserialize<SceneDocument>(source.Pop())!;if(Selected==null)canvas.SelectedId=null;Changed(true);Inspector();}
 void RefreshList(){updating=true;objects.ItemsSource=Document.Items.AsEnumerable().Reverse().ToArray();objects.ItemTemplate=new Avalonia.Controls.Templates.FuncDataTemplate<SceneItem>((x,_)=>{if(x==null)return new TextBlock();var row=new DockPanel{LastChildFill=true};var padlock=new Button{Content=x.Locked?"🔒":"🔓",Padding=new Thickness(7,3),Margin=new Thickness(6,0,0,0)};Avalonia.Automation.AutomationProperties.SetName(padlock,(x.Locked?"Desbloquear ":"Bloquear ")+x.Name);ToolTip.SetTip(padlock,x.Locked?"Desbloquear objeto":"Bloquear objeto");padlock.Click+=(_,e)=>{Checkpoint();x.Locked=!x.Locked;canvas.SelectedId=x.Id;Changed(true);Inspector();e.Handled=true;};DockPanel.SetDock(padlock,Dock.Right);row.Children.Add(padlock);var grip=new TextBlock{Text="⠿",Margin=new Thickness(0,0,7,0),Cursor=new Cursor(StandardCursorType.SizeAll),VerticalAlignment=VerticalAlignment.Center};ToolTip.SetTip(grip,"Arrastra para cambiar el orden de la capa");row.Children.Add(grip);row.Children.Add(new TextBlock{Text=(x.Visible?"● ":"◌ ")+x.Name,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(4)});var target=new Border{Child=row,Padding=new Thickness(0,2)};LayerDrop(target,x,grip);return target;});objects.SelectedItem=Selected;updating=false;}
 public void ReorderLayer(string source,string target,bool before){var order=Document.Items.AsEnumerable().Reverse().ToList();var item=order.FirstOrDefault(x=>x.Id==source);var destination=order.FirstOrDefault(x=>x.Id==target);if(item==null||destination==null||source==target)return;order.Remove(item);order.Insert(order.IndexOf(destination)+(before?0:1),item);if(order.AsEnumerable().Reverse().SequenceEqual(Document.Items))return;Checkpoint();Document.Items=order.AsEnumerable().Reverse().ToList();canvas.SelectedId=source;Changed(true);Inspector();}
 void ClearDrop(){if(dropIndicator!=null){dropIndicator.BorderThickness=new Thickness(0);dropIndicator=null;}}
 void LayerDrop(Border row,SceneItem item,Control grip){
  grip.PointerPressed+=async(_,e)=>{if(!e.GetCurrentPoint(grip).Properties.IsLeftButtonPressed)return;e.Handled=true;layerDrag=item.Id;canvas.SelectedId=item.Id;objects.SelectedItem=item;Inspector();var data=new DataTransfer();data.Add(DataTransferItem.CreateText(item.Id));try{await DragDrop.DoDragDropAsync(e,data,DragDropEffects.Move);}finally{layerDrag=null;ClearDrop();}};
  DragDrop.SetAllowDrop(row,true);
  row.AddHandler(DragDrop.DragOverEvent,(_,e)=>{if(layerDrag==null){e.DragEffects=DragDropEffects.None;return;}e.DragEffects=DragDropEffects.Move;ClearDrop();dropIndicator=row;row.BorderBrush=Brushes.DeepSkyBlue;row.BorderThickness=e.GetPosition(row).Y<row.Bounds.Height/2?new Thickness(0,2,0,0):new Thickness(0,0,0,2);var point=e.GetPosition(objects);var scroll=objects.GetVisualDescendants().OfType<ScrollViewer>().FirstOrDefault();if(scroll!=null&&(point.Y<20||point.Y>objects.Bounds.Height-20))scroll.Offset=new Vector(scroll.Offset.X,Math.Max(0,scroll.Offset.Y+(point.Y<20?-18:18)));e.Handled=true;});
  row.AddHandler(DragDrop.DropEvent,(_,e)=>{if(layerDrag is{} source){bool before=e.GetPosition(row).Y<row.Bounds.Height/2;ClearDrop();ReorderLayer(source,item.Id,before);e.Handled=true;}});
