 async Task Add(string kind,string? path=null){try{if(Document.Items.Count>=256)throw new InvalidOperationException("Este diseño ya tiene 256 objetos.");if(kind is "image" or "widget"){if(path==null){var files=await StorageProvider.OpenFilePickerAsync(new FilePickerOpenOptions{Title=kind=="image"?"Añadir imagen o GIF":"Añadir widget HTML o ZIP",AllowMultiple=false,FileTypeFilter=[new FilePickerFileType(kind=="image"?"Imágenes y GIF":"Widgets HTML"){Patterns=kind=="image"?["*.png","*.jpg","*.jpeg","*.webp","*.gif","*.bmp"]:["*.html","*.htm","*.zip"]}]});if(files.Count==0)return;path=files[0].TryGetLocalPath();}if(path==null)return;path=await Task.Run(()=>AssetStore.Import(path,kind=="widget"));}Checkpoint();var item=SceneDocument.New(kind,canvas.Bounds.Size,draft);if(path!=null){item.Asset=path;item.Name=Path.GetFileNameWithoutExtension(path);if(kind=="image"){using var image=new ImageFrames(path);double h=item.Width*canvas.Bounds.Width*image.Height/image.Width/canvas.Bounds.Height;item.Height=Math.Min(1,h);item.Width=item.Height*canvas.Bounds.Height*image.Width/image.Height/canvas.Bounds.Width;}}Document.Items.Add(item);canvas.SelectedId=item.Id;Changed(true);Inspector();}catch(Exception e){await Message("No se pudo añadir el objeto",e.Message);}}
